// Intent Router — "Run Once for Each Item"
// Accepts input from either trigger (Chat Trigger → chatInput, Webhook → body.question)
// and intercepts *pure* greetings before any embedding or database work.
const question = String(
  $json.chatInput ?? $json.body?.question ?? $json.body?.chatInput ?? ''
).trim();

// Whole-message match only: "Hi!" is a greeting, "Hi, how do I give feedback?" is a question.
const GREETING = /^(hi|hello|hey|hiya|howdy|greetings|good\s+(morning|afternoon|evening)|salam|assalamu\s+alaikum|marhaba|مرحبا|اهلا|السلام عليكم)(\s+(there|sara|dr\.?\s*sara|dr\.?\s*hegy))?[\s!.,?]*$/i;

const intent = question === '' || GREETING.test(question) ? 'greeting' : 'question';

return { json: { question, intent } };

// Build Persona Prompt — "Run Once for Each Item"
// Only reached when at least one chunk passed the SQL gate.
// Frameworks supply WHAT to say; voice samples supply HOW Dr. Sara says it.
const MODEL = 'qwen3:4b-instruct';
const { question } = $('Intent Router').item.json;
const { frameworks, voice_samples } = $json;

const frameworkNotes = frameworks.length
  ? frameworks.map((f) => `[${f.session_id}] ${f.content}`).join('\n\n')
  : '(none retrieved)';
const voiceNotes = voice_samples.length
  ? voice_samples.map((v) => `[${v.session_id}] "${v.content}"`).join('\n\n')
  : '(none retrieved)';

const systemPrompt = `You are Dr. Sara Hegy, an executive coach. You answer a leader's question using the coaching frameworks in FRAMEWORK NOTES, and you speak exactly the way the VOICE SAMPLES show you speaking.

How you answer:
- Open by reframing the leader's problem as a system or architecture issue, in one or two short, direct sentences.
- Name the framework from FRAMEWORK NOTES and explain its logic in plain language, using its own terms.
- Speak to the leader as "you", in short declarative sentences, with the vocabulary and rhythm of the VOICE SAMPLES.
- Close with one concrete action the leader takes this week.
- Keep the answer between 120 and 180 words.
The first exchange below is a format example built on a demo framework; your real answer draws only on the notes in the final message.`;

// Positive few-shot: one complete example of the target shape and tone.
const exampleUser = `FRAMEWORK NOTES:
[DEMO] Framework: The Decision Ledger
Every recurring decision is logged with an owner and a decision rule. Escalations drop when ownership is explicit; the leader reviews the ledger weekly instead of the decisions themselves.

VOICE SAMPLES:
[DEMO] "Look, your inbox is not the problem. Your decision rights are. When ownership is fuzzy, everything floats up to you."

QUESTION: My managers escalate every small decision to me. What should I do?`;

const exampleAssistant = `Look, the escalations are not a people problem. They are a decision-rights problem. When ownership is fuzzy, every choice floats up to your desk, and your calendar pays the price.

We fix this with the Decision Ledger. You list the decisions that keep landing on you, and for each one you assign a clear owner and a simple decision rule. Once the rule is written down, your managers stop asking permission and start applying the standard. You move from approving decisions to reviewing the ledger once a week.

This week, pull the last ten escalations from your inbox. Give each one an owner and a one-line rule, and share the ledger with your managers on Monday.`;

const userPrompt = `FRAMEWORK NOTES:
${frameworkNotes}

VOICE SAMPLES:
${voiceNotes}

QUESTION: ${question}`;

return {
  json: {
    question,
    frameworks,
    voice_samples,
    llm_request: {
      model: MODEL,
      stream: false,
      options: { temperature: 0.3, num_ctx: 8192 },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: exampleUser },
        { role: 'assistant', content: exampleAssistant },
        { role: 'user', content: userPrompt },
      ],
    },
  },
};

// Format Answer — "Run Once for Each Item"
const prompt = $('Build Persona Prompt').item.json;
const answer = String($json.message?.content ?? '').trim();

const sources = [...prompt.frameworks, ...prompt.voice_samples].map((c) => ({
  session_id: c.session_id,
  stream_type: c.stream_type,
  chunk_index: c.chunk_index,
  similarity: Number(Number(c.similarity).toFixed(4)),
}));

const sourceLine = sources
  .map((s) => `${s.session_id} ${s.stream_type}#${s.chunk_index} (${s.similarity.toFixed(3)})`)
  .join(', ');

return {
  json: {
    route: 'persona_answer',
    question: prompt.question,
    output: `${answer}\n\nSources: ${sourceLine}`,
    answer,
    sources,
  },
};
